alter table public.hotel_websites
  add column if not exists sections jsonb not null default '[{"id":"hero","enabled":true},{"id":"about","enabled":true},{"id":"benefits","enabled":true},{"id":"gallery","enabled":true},{"id":"booking","enabled":true},{"id":"contact","enabled":true}]'::jsonb,
  add column if not exists published_sections jsonb not null default '[{"id":"hero","enabled":true},{"id":"about","enabled":true},{"id":"benefits","enabled":true},{"id":"gallery","enabled":true},{"id":"booking","enabled":true},{"id":"contact","enabled":true}]'::jsonb,
  add column if not exists draft_snapshot jsonb,
  add column if not exists published_snapshot jsonb,
  add column if not exists draft_saved_at timestamptz,
  add column if not exists published_at timestamptz,
  add column if not exists published_version integer not null default 0,
  add column if not exists default_language text not null default 'es',
  add column if not exists languages text[] not null default array['es']::text[],
  add column if not exists floating_booking_enabled boolean not null default true,
  add column if not exists floating_booking_label text not null default 'Reservar',
  add column if not exists floating_booking_position text not null default 'bottom_right',
  add column if not exists external_platform text,
  add column if not exists domain_last_checked_at timestamptz,
  add column if not exists domain_error text,
  add column if not exists domain_verification jsonb,
  add column if not exists analytics_enabled boolean not null default true;

alter table public.hotel_websites drop constraint if exists hotel_websites_default_language_check;
alter table public.hotel_websites add constraint hotel_websites_default_language_check check(default_language in('es','en','pt'));
alter table public.hotel_websites drop constraint if exists hotel_websites_floating_position_check;
alter table public.hotel_websites add constraint hotel_websites_floating_position_check check(floating_booking_position in('bottom_right','bottom_left'));

create table if not exists public.hotel_website_revisions(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,version integer not null,snapshot jsonb not null,published_by uuid default auth.uid(),created_at timestamptz not null default now(),unique(property_id,version));
alter table public.hotel_website_revisions enable row level security;
drop policy if exists hotel_website_revisions_select on public.hotel_website_revisions;
create policy hotel_website_revisions_select on public.hotel_website_revisions for select using(private.user_has_property_access(property_id));
drop policy if exists hotel_website_revisions_insert on public.hotel_website_revisions;
create policy hotel_website_revisions_insert on public.hotel_website_revisions for insert with check(private.user_has_property_role(property_id,array['owner','manager','admin']::text[]));
create index if not exists idx_hotel_website_revisions_property_created on public.hotel_website_revisions(property_id,created_at desc);

create table if not exists public.hotel_web_events(id bigint generated by default as identity primary key,property_id uuid not null references public.properties(id) on delete cascade,event_name text not null check(event_name in('site_view','engine_view','availability_search','availability_result','booking_start','booking_confirmed')),source text not null default 'direct',session_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.hotel_web_events enable row level security;
drop policy if exists hotel_web_events_select on public.hotel_web_events;
create policy hotel_web_events_select on public.hotel_web_events for select using(private.user_has_property_access(property_id));
create index if not exists idx_hotel_web_events_property_created on public.hotel_web_events(property_id,created_at desc);
create index if not exists idx_hotel_web_events_property_event on public.hotel_web_events(property_id,event_name,created_at desc);

create or replace function public.hl_public_web_event(p_slug text,p_event text,p_source text default 'direct',p_session text default null,p_metadata jsonb default '{}'::jsonb) returns boolean language plpgsql security definer set search_path='public','pg_temp' as $$
declare v_property uuid;
begin
  if p_event not in('site_view','engine_view','availability_search','availability_result','booking_start','booking_confirmed') then return false; end if;
  select property_id into v_property from public.hotel_booking_engines where slug=lower(trim(p_slug)) and enabled=true limit 1;
  if v_property is null then return false; end if;
  insert into public.hotel_web_events(property_id,event_name,source,session_id,metadata) values(v_property,p_event,left(coalesce(nullif(trim(p_source),''),'direct'),40),left(coalesce(p_session,''),80),case when jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))='object' then coalesce(p_metadata,'{}'::jsonb) else '{}'::jsonb end);
  return true;
end;$$;
revoke all on function public.hl_public_web_event(text,text,text,text,jsonb) from public;
grant execute on function public.hl_public_web_event(text,text,text,text,jsonb) to anon,authenticated;

create or replace function public.hl_website_funnel(p_property_id uuid,p_days integer default 30) returns jsonb language sql stable security invoker set search_path='public','pg_temp' as $$
with base as(select event_name,source,session_id from public.hotel_web_events where property_id=p_property_id and created_at>=now()-(least(greatest(coalesce(p_days,30),1),90)||' days')::interval),counts as(select count(*) filter(where event_name='site_view') site_views,count(*) filter(where event_name='engine_view') engine_views,count(*) filter(where event_name='availability_search') searches,count(*) filter(where event_name='availability_result') results,count(*) filter(where event_name='booking_start') starts,count(*) filter(where event_name='booking_confirmed') confirmed,count(distinct nullif(session_id,'')) sessions from base),sources as(select coalesce(jsonb_object_agg(source,cnt),'{}'::jsonb) data from(select source,count(*) cnt from base where event_name='engine_view' group by source order by count(*) desc)q)
select jsonb_build_object('days',least(greatest(coalesce(p_days,30),1),90),'site_views',c.site_views,'engine_views',c.engine_views,'searches',c.searches,'results',c.results,'booking_starts',c.starts,'confirmed',c.confirmed,'sessions',c.sessions,'conversion_pct',case when c.engine_views>0 then round((c.confirmed::numeric/c.engine_views::numeric)*100,1) else 0 end,'sources',s.data) from counts c cross join sources s;$$;
grant execute on function public.hl_website_funnel(uuid,integer) to authenticated;

create or replace function public.hl_public_booking_config(p_slug text) returns jsonb language plpgsql security definer set search_path='public','pg_temp' as $$
declare e public.hotel_booking_engines%rowtype;p public.properties%rowtype;w public.hotel_websites%rowtype;v_default jsonb;v_policies jsonb;v_vouchers jsonb;
begin
  select * into e from public.hotel_booking_engines where slug=lower(trim(p_slug)) and enabled=true;if not found then raise exception 'Motor no disponible';end if;
  select * into p from public.properties where id=e.property_id;select * into w from public.hotel_websites where property_id=e.property_id;
  select to_jsonb(cp) into v_default from public.hotel_cancellation_policies cp where cp.property_id=e.property_id and cp.active=true and cp.visible_in_booking_engine=true order by cp.is_default desc,cp.created_at asc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('id',cp.id,'code',cp.code,'name',cp.name,'description',cp.description,'policy_type',cp.policy_type,'cancellation_rules',cp.cancellation_rules,'no_show_rule',cp.no_show_rule,'early_checkout_rule',cp.early_checkout_rule,'prepayment_required',cp.prepayment_required,'prepayment_percent',cp.prepayment_percent,'is_default',cp.is_default) order by cp.is_default desc,cp.name),'[]'::jsonb) into v_policies from public.hotel_cancellation_policies cp where cp.property_id=e.property_id and cp.active=true and cp.visible_in_booking_engine=true;
  select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'name',v.name,'slug',v.slug,'language',v.language,'description',v.description,'image_url',v.image_url,'commercial_conditions',v.commercial_conditions,'price_mode',v.price_mode,'price',v.price,'currency',v.currency,'tax_included',v.tax_included,'tax_percent',v.tax_percent,'date_mode',v.date_mode,'stay_type',v.stay_type,'nights',v.nights,'room_type',v.room_type,'inventory_mode',v.inventory_mode,'inventory_quantity',v.inventory_quantity,'validity_mode',v.validity_mode,'valid_from',v.valid_from,'valid_to',v.valid_to,'visibility',v.visibility) order by v.sort_order,v.name),'[]'::jsonb) into v_vouchers from public.hotel_vouchers v where v.property_id=e.property_id and v.active=true and coalesce((v.visibility->>'booking_engine')::boolean,true)=true and(v.validity_mode='unlimited' or v.valid_to>=current_date);
  return jsonb_build_object('slug',e.slug,'property_id',e.property_id,'name',coalesce(nullif(e.display_name,''),p.name),'city',p.city,'description',p.description,'currency',e.currency,'primary_color',e.primary_color,'accent_color',e.accent_color,'logo_url',e.logo_url,'hero_url',e.hero_url,'booking_message',e.booking_message,'confirmation_message',e.confirmation_message,'contact_phone',e.contact_phone,'contact_email',e.contact_email,'allowed_origins',e.allowed_origins,'min_advance_days',e.min_advance_days,'max_advance_days',e.max_advance_days,'min_nights',e.min_nights,'template',e.template,'cancellation_policy',coalesce(v_default->>'description',e.cancellation_policy),'default_cancellation_policy',v_default,'cancellation_policies',v_policies,'terms_url',e.terms_url,'privacy_url',e.privacy_url,'payment_mode',e.payment_mode,'deposit_percent',e.deposit_percent,'room_type_rules',e.room_type_rules,'gallery',e.gallery,'seo_title',e.seo_title,'seo_description',e.seo_description,'allow_self_cancel',e.allow_self_cancel,'self_cancel_cutoff_hours',e.self_cancel_cutoff_hours,'withdrawal_button_enabled',true,'website_mode',coalesce(w.mode,'managed'),'website_enabled',coalesce(w.enabled,true),'website_custom_domain',w.custom_domain,'website_domain_status',coalesce(w.domain_status,'not_connected'),'website_seo_indexable',coalesce(w.seo_indexable,true),'website_seo_canonical_url',w.seo_canonical_url,'website_sections',coalesce(w.published_sections,w.sections,'[]'::jsonb),'website_languages',coalesce(w.languages,array['es']::text[]),'website_default_language',coalesce(w.default_language,'es'),'floating_booking_enabled',coalesce(w.floating_booking_enabled,true),'floating_booking_label',coalesce(nullif(w.floating_booking_label,''),'Reservar'),'floating_booking_position',coalesce(w.floating_booking_position,'bottom_right'),'analytics_enabled',coalesce(w.analytics_enabled,true),'analytics_ga4_id',w.analytics_ga4_id,'analytics_gtm_id',w.analytics_gtm_id,'analytics_meta_pixel_id',w.analytics_meta_pixel_id,'vouchers',v_vouchers);
end;$$;
